mapper.select:
SELECT
    max(class_head_id) class_head_id
FROM
    hls_asset_class_head
WHERE
    bp_id = #{bpId}
  AND class_year =  #{classYear}
  AND class_season =  #{classSeason}
  AND approve_status = 'APPROVED'

select hac.class_head_id, hac.batch_num, hac.class_year, hac.class_season, hac.description, (SELECT scv.meaning FROM sys_code_b scb, sys_code_value_b scv WHERE scb.CODE = 'QUARTER' AND scb.CODE_ID = scv.CODE_ID and scv.value = hac.class_season) class_season_n, hac.submit_by, (select su.description from sys_user su where su.user_id = hac.submit_by) submit_by_n, hac.unit_id, (select fou.unit_name from fnd_org_unit fou where fou.unit_id = hac.unit_id) unit_id_n, hac.approve_time, to_char(hac.approve_time, 'YYYY-MM-DD') approve_time_n, hac.approve_status, (SELECT scv.meaning FROM sys_code_b scb, sys_code_value_b scv WHERE scb.CODE = 'HLS_WFL_STATUS' AND scb.CODE_ID = scv.CODE_ID and scv.value = hac.approve_status) approve_status_n, hac.bp_id, (SELECT HBM.BP_NAME FROM HLS_BP_MASTER HBM WHERE HBM.BP_ID = HAC.BP_ID) bp_name, hac.document_type, (SELECT scv.meaning FROM sys_code_b scb, sys_code_value_b scv WHERE scb.CODE = 'HLS_ASSET_CLASS_HEAD_TYPE' AND scb.CODE_ID = scv.CODE_ID and scv.value = hac.document_type) DOCUMENT_TYPE_N, nvl((select count(HACL.class_line_id) from HLS_ASSET_CLASS_LINE HACL where HACL.class_head_id = hac.class_head_id), 0) CONTRACT_QUANTITY from hls_asset_class_head hac
and hac.class_head_id = #{classHeadId}
and hac.approve_status = #{approveStatus}
and hac.batch_num = #{batchNum}
and hac.class_year = #{classYear}
and hac.class_season = #{classSeason}
and hac.document_type = #{documentType}
and hac.bp_id = #{bpId}
and hac.bp_id in
#{item}
order by hac.batch_num desc

SELECT hac.class_head_id, hac.batch_num, hac.class_year, hac.class_season, hac.description, ( SELECT scv.meaning FROM sys_code_b scb, sys_code_value_b scv WHERE scb.CODE = 'QUARTER' AND scb.CODE_ID = scv.CODE_ID AND scv.value = hac.class_season ) class_season_n, hac.submit_by, ( SELECT su.description FROM sys_user su WHERE su.user_id = hac.submit_by ) submit_by_n, hac.unit_id, ( SELECT fou.unit_name FROM fnd_org_unit fou WHERE fou.unit_id = hac.unit_id ) unit_id_n, hac.approve_time, to_char( hac.approve_time, 'YYYY-MM-DD' ) approve_time_n, hac.approve_status, ( SELECT scv.meaning FROM sys_code_b scb, sys_code_value_b scv WHERE scb.CODE = 'HLS_WFL_STATUS' AND scb.CODE_ID = scv.CODE_ID AND scv.value = hac.approve_status ) approve_status_n, hac.bp_id, ( SELECT HBM.BP_NAME FROM HLS_BP_MASTER HBM WHERE HBM.BP_ID = HAC.BP_ID ) bp_name, hac.document_type, ( SELECT scv.meaning FROM sys_code_b scb, sys_code_value_b scv WHERE scb.CODE = 'HLS_ASSET_CLASS_HEAD_TYPE' AND scb.CODE_ID = scv.CODE_ID AND scv.value = hac.document_type ) DOCUMENT_TYPE_N, nvl( ( SELECT count( HACL.class_line_id ) FROM HLS_ASSET_CLASS_LINE HACL WHERE HACL.class_head_id = hac.class_head_id ), 0 ) CONTRACT_QUANTITY, HACL.CLASS_LINE_ID, HACL.CONTRACT_ID, HACL.CONTRACT_NUMBER, HACL.BUSINESS_TYPE, ( SELECT hbt.DESCRIPTION FROM HLS_BUSINESS_TYPE hbt WHERE hbt.BUSINESS_TYPE = HACl.BUSINESS_TYPE AND hbt.document_category = 'CONTRACT' ) AS BUSINESS_TYPE_N, HACL.INITIAL_LEVEL, ( SELECT scv.meaning FROM sys_code_b scb, sys_code_value_b scv WHERE scb.CODE = 'ASSET_CLASS' AND scb.CODE_ID = scv.CODE_ID AND scv.value = HACL.INITIAL_LEVEL ) INITIAL_LEVEL_N, HACL.REVIEW_LEVEL, ( SELECT scv.meaning FROM sys_code_b scb, sys_code_value_b scv WHERE scb.CODE = 'ASSET_CLASS' AND scb.CODE_ID = scv.CODE_ID AND scv.value = HACl.REVIEW_LEVEL ) REVIEW_LEVEL_N, HACL.CONTRACT_AMOUNT, HACL.DELIVERY_TIME, TO_CHAR( HACL.DELIVERY_TIME, 'YYYY-MM-DD' ) DELIVERY_TIME_N, HACL.LEASE_TERM, round( (select sum(nvl(ccc.due_amount,0) - nvl(ccc.received_amount, 0)) from con_contract_cashflow ccc where ccc.contract_id = cc.contract_id and ccc.cf_type = 1), 2) REMAINING_RENT, round( (select sum(nvl(ccc.principal,0) - nvl(ccc.received_principal, 0)) from con_contract_cashflow ccc where ccc.contract_id = cc.contract_id and ccc.cf_type = 1), 2) REMAINING_PRINCIPAL,
( SELECT sum( nvl( ccc.principal, 0 ) - nvl( ccc.received_principal, 0 ) ) FROM con_contract cc, con_contract_cashflow ccc WHERE ccc.contract_id = cc.contract_id AND ccc.cf_type = 1 AND cc.CONTRACT_NUMBER = HACL.CONTRACT_NUMBER GROUP BY cc.CONTRACT_NUMBER ) AS REMAINING_PRINCIPAL_WO, HACL.OVERDUE_RENT, HACL.OVERDUE_DAYS, HACL.FX_OVERDUE_RENT, HACL.FX_OVERDUE_DAYS, HACL.PENALTY_INTEREST, nvl(round((select sum(nvl(csh.transaction_amount, 0)) - sum(nvl(csh.write_off_amount, 0)) from csh_transaction csh where csh.contract_id = cc.contract_id and csh.business_type = 'DEPOSIT'), 2), 0) REMAINING_MARGIN, (round( (select sum(nvl(ccc.principal,0) - nvl(ccc.received_principal, 0)) from con_contract_cashflow ccc where ccc.contract_id = cc.contract_id and ccc.cf_type = 1), 2) - nvl(round((select sum(nvl(csh.transaction_amount, 0)) - sum(nvl(csh.write_off_amount, 0)) from csh_transaction csh where csh.contract_id = cc.contract_id and csh.business_type = 'DEPOSIT'), 2), 0)) REMAINING_EXPOSURE,
( SELECT hbm.BP_NAME FROM HLS_BP_MASTER hbm WHERE cc.BP_ID_VENDER = hbm.BP_ID ) BP_ID_VENDER, ( SELECT hbm.BP_NAME FROM HLS_BP_MASTER hbm WHERE cc.FACTORY_ID = hbm.BP_ID ) FACTORY_NAME FROM hls_asset_class_head hac LEFT JOIN HLS_ASSET_CLASS_LINE hacl ON hac.CLASS_HEAD_ID = hacl.CLASS_HEAD_ID INNER JOIN CON_CONTRACT cc ON hacl.CONTRACT_ID = cc.CONTRACT_ID
and hac.class_head_id = #{classHeadId}
and hac.approve_status = #{approveStatus}
and hac.batch_num = #{batchNum}
and hac.class_year = #{classYear}
and hac.class_season = #{classSeason}
and hac.document_type = #{documentType}
and hac.bp_id in
#{item}
and cc.BP_ID_VENDER = #{bpIdVender}
and cc.FACTORY_ID = #{factoryId}
order by hac.batch_num desc
